iption\": null, \"id\": 11, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [1454, 92, 1494, 127], \"page_id\": 5}], \"content\": \"VII\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [310, 214, 1324, 288], \"page_id\": 5}], \"content\": \"Nonquarterly Tables and Reports\", \"description\": null, \"id\": 1, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [310, 321, 1322, 396], \"page_id\": 5}], \"content\": \"For the convenience of the \\\"Treasury Bulletin\\\" user, nonquarterly tables and reports are listed below along with the issues in which they appear.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [168, 427, 1488, 1883], \"page_id\": 5}], \"content\": \"<table><tr><th></th><th colspan=\\\"4\\\">Issues</th></tr><tr><th></th><th>March</th><th>June</th><th>Sept.</th><th>Dec.</th></tr><tr><td><b>Federal Fiscal Operations</b></td><td></td><td></td><td></td><td></td></tr><tr><td>FFO-5.\\u2014Internal Revenue Receipts by State</td><td></td><td></td><td></td><td>&#10004;</td></tr><tr><td>FFO-6.\\u2014Customs and Border Protection Collection of Duties, Taxes and Fees by Districts and Ports</td><td></td><td></td><td></td><td>&#10004;</td></tr><tr><td><b>Special Reports</b></td><td></td><td></td><td></td><td></td></tr><tr><td>Financial Report of the United States Government excerpt</td><td>&#10004;</td><td></td><td></td><td></td></tr><tr><td>Trust Fund Reports:</td><td></td><td></td><td></td><td></td></tr><tr><td>Airport and Airway Trust Fund</td><td>&#10004;</td><td></td><td></td><td></td></tr><tr><td>Black Lung Disability Trust Fund</td><td>&#10004;</td><td></td><td></td><td></td></tr><tr><td>Civil Service Retirement and Disability Fund *</td><td></td><td></td><td></td><td>&#10004;</td></tr><tr><td>Federal Disability Insurance Trust Fund *</td><td></td><td></td><td></td><td>&#10004;</td></tr><tr><td>Federal Hospital Insurance Trust Fund *</td><td></td><td></td><td></td><td>&#10004;</td></tr>