27</td><td>11,538</td></tr><tr><td>2004</td><td>7,237</td><td>2,962</td><td>8,546</td><td>10,179</td></tr><tr><td>2005</td><td>5,848</td><td>2,973</td><td>7,695</td><td>7,411</td></tr><tr><td>2005 - Mar</td><td>5,688</td><td>4,587</td><td>7,692</td><td>10,845</td></tr><tr><td>Apr</td><td>5,848</td><td>4,862</td><td>7,692</td><td>11,139</td></tr><tr><td>May</td><td>5,848</td><td>5,121</td><td>7,692</td><td>11,686</td></tr><tr><td>June</td><td>5,848</td><td>2,170</td><td>7,692</td><td>11,543</td></tr><tr><td>July</td><td>5,848</td><td>2,447</td><td>7,695</td><td>11,826</td></tr><tr><td>Aug</td><td>5,848</td><td>2,695</td><td>7,695</td><td>11,845</td></tr><tr><td>Sept</td><td>5,848</td><td>2,973</td><td>7,695</td><td>7,411</td></tr><tr><td>Oct</td><td>5,848</td><td>3,250</td><td>7,695</td><td>6,289</td></tr><tr><td>Nov</td><td>5,848</td><td>3,504</td><td>9,506</td><td>16,358</td></tr><tr><td>Dec</td><td>5,848</td><td>3,787</td><td>9,506</td><td>18,056</td></tr><tr><td>2006 - Jan</td><td>5,848</td><td>4,068</td><td>11,624</td><td>20,615</td></tr><tr><td>Feb</td><td>5,848</td><td>4,309</td><td>12,953</td><td>22,711</td></tr><tr><td>Mar</td><td>4,911</td><td>4,582</td><td>9,303</td><td>23,505</td></tr></table>\", \"description\": null, \"id\": 4, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [155, 1820, 526, 1841], \"page_id\": 35}], \"content\": \"Note.\\u2014Detail may not add to totals due to rounding.\", \"description\": null, \"id\": 5, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [1390, 2051, 1488, 2074], \"page_id\": 35}], \"content\": \"June 2006\", \"description\": null, \"id\": 6, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [140, 97, 175, 127], \"page_id\": 36}], \"content\": \"32\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [450, 212, 1178, 252], \"page_id\": 36}], \"content\": \"INTRODUCTION: Public Debt Operations\", \"description\": null, \"id\": 1, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [140, 266, 798, 575], \"page_id\": 36}], \"content\": \"Chapter 31 of Title 31 of the United States Code allows the Secretary of Treasury to borrow money by issuing Treasury securities. The Secretary determines the terms and conditions of issue, conversion, maturity, payment, and interest rate. New issues of Treasury notes mature in 2 to 10 years. Bonds mature in more than 10 years from the issue date. Each outstanding marketable security is listed in the \\\"Monthly Statement of the Public Debt of the United States.\\\" The information in this section of the \\\"Treasury Bulletin\\\" pertains only to marketable Treasury securities.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 589, 798, 806], \"page_id\": 36}], \"content\": \"Table PDO-1 provides a maturity schedule of interest-bearing marketable Treasury notes and bonds. All unmatured Treasury notes and bonds are listed in maturity order, from earliest to latest. A separate breakout is provided for the combined holdings of the Government accounts and Federal Reserve banks (FRBs), so that the \\\"all other investors\\\" category includes all private holdings.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 808, 798, 874], \"page_id\": 36}], \"content\": \"Table PDO-2 presents the results of weekly auctions of 4-, 13-, and 26-week bills. Treasury bills mature each\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [829, 266, 1494, 422], \"page_id\": 36}], \"content\": \"Thursday. Issues of 4- and 13-week bills are reopenings of 26-week bills. Issues of cash management bills also are presented. High yields on accepted tenders and the dollar value of total bids are presented, with the dollar value of awards made on both competitive and noncompetitive bases.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [829, 422, 1490, 542], \"page_id\": 36}], \"content\": \"To encourage the participation of individuals and smaller institutions, Treasury accepts noncompetitive tenders of up to $5 million for bills and $5 million for notes and bonds in each auction of securities.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [829, 559, 1490, 653], \"page_id\": 36}], \"content\": \"Table PDO-3 lists the results of auctions of marketable securities, other than weekly bills, in chronological order over the past 2 years.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 679, 1490, 839], \"page_id\": 36}], \"content\": \"Note: Additional information, including auction allotments by investor class for marketable Treasury coupon and bill securities, is posted on the 7th business day of each month at http://www.treas.gov/offices/domestic-finance/debt-management/investor_class_auction.shtml.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [415, 940, 1211, 981], \"page_id\": 36}], \"content\": \"TREASURY FINANCING: JANUARY-MARCH\", \"description\": null, \"id\": 9, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [616, 1016, 1018, 1047], \"page_id\": 36}], \"content\": \"[Source: Bureau of the Public Debt, Office of Financing]\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 1056, 352, 1091], \"page_id\": 36}], \"content\": \"JANUARY\", \"description\": null, \"id\": 11, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [140, 1117, 444, 1155], \"page_id\": 36}], \"content\": \"Cash Management Bills\", \"description\": null, \"id\": 12, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [140, 1172, 798, 1391], \"page_id\": 36}], \"content\": \"On December 27, 2005, Treasury announced it would auction $12,000 million of 14-day bills. They were issued January 3, 2006, and matured January 17. The issue was to raise new cash. Treasury auctioned the bills on December 29. Tenders totaled $25,200 million; Treasury accepted $12,000 million. The high bank discount rate was 4.100 percent.\", \"description\": null, \"id\": 13, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 1412, 446, 1445], \"page_id\": 36}], \"content\": \"Auction of 2-Year Notes\", \"description\": null, \"id\": 14, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [140, 1464, 798, 1619], \"page_id\": 36}], \"content\": \"On December 27, 2005, Treasury announced it would auction $20,000 million of 2-year notes of Series Y-2007. The issue was to refund $26,009 million of securities maturing December 31 and to pay down approximately $6,009 million.\", \"description\": null, \"id\": 15, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 1631, 798, 1815], \"page_id\": 36}], \"content\": \"The notes of Series Y-2007 were dated December 31, 2005, and issued on January 3, 2006. They are due December 31, 2007, with interest payable on June 30 and December 31 until maturity. Treasury set an interest rate of 4-3/8 percent after determining which tenders were accepted on a yield auction basis.\", \"description\": null, \"id\": 16, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 1822, 798, 1914], \"page_id\": 36}], \"content\": \"Treasury received tenders for the notes before 12 noon eastern standard time (e.s.t.) for noncompetitive tenders and before 1 p.m. e.s.t. for competitive tenders on December 29.\", \"description\": null, \"id\": 17, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 1056, 1492, 1428], \"page_id\": 36}], \"content\": \"Tenders totaled $48,320 million; Treasury accepted $20,000 million. All noncompetitive and successful competitive bidders were allotted securities at the high yield of 4.404 percent with the equivalent price of $99.944505. Treasury accepted in full all competitive tenders at yields lower than 4.404 percent. Tenders at the high yield were allotted 6.00 percent. The median yield was 4.383 percent, and the low yield was 4.350 percent. Noncompetitive tenders totaled $920 million. Competitive tenders accepted from private investors totaled $19,080 million. Accrued interest of $0.36257 per $1,000 must be paid for the period from December 31, 2005, to January 3, 2006.\", \"description\": null, \"id\": 18, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 1433, 1490, 1589], \"page_id\": 36}], \"content\": \"In addition to the $20,000 million of tenders accepted in the auction process, Treasury accepted $6,667 million from Federal Reserve Banks (FRBs) for their own accounts. The minimum par amount required for STRIPS of notes of Series Y-2007 is $1,000.\", \"description\": null, \"id\": 19, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 1608, 1140, 1643], \"page_id\": 36}], \"content\": \"Auction of 5-Year Notes\", \"description\": null, \"id\": 20, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [831, 1664, 1490, 1758], \"page_id\": 36}], \"content\": \"On January 9, 2006, Treasury announced it would auction $13,000 million of 5-year notes of Series D-2011. The issue was to raise new cash.\", \"description\": null, \"id\": 21, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 1768, 1490, 1893], \"page_id\": 36}], \"content\": \"The notes of Series D-2011 were dated January 15 and issued January 17. They are due January 15, 2011, with interest payable on July 15 and January 15 until maturity. Treasury set an interest rate of 4-1/4 percent after\", \"description\": null, \"id\": 22, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 2039, 246, 2070], \"page_id\": 36}], \"content\": \"June 2006\", \"description\": null, \"id\": 23, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [630, 94, 1002, 127], \"page_id\": 37}], \"content\": \"PUBLIC DEBT OPERATIONS\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1455, 97, 1494, 130], \"page_id\": 37}], \"content\": \"33\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [368, 193, 1257, 236], \"page_id\": 37}], \"content\": \"TREASURY FINANCING: JANUARY-MARCH, con.\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [133, 269, 801, 330], \"page_id\": 37}], \"content\": \"determining which tenders were accepted on a yield auction basis.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [137, 344, 807, 830], \"page_id\": 37}], \"content\": \"Treasury received tenders for the notes before 12 noon e.s.t. for noncompetitive tenders and before 1:00 p.m. e.s.t. for competitive tenders on January 11. Tenders totaled $27,260 million; Treasury accepted $13,000 million. All noncompetitive and successful competitive bidders were allotted securities at the high yield of 4.370 percent with an equivalent price of $99.466250. Treasury accepted in full all competitive tenders at yields lower than 4.370 percent. Tenders at the high yield were allotted 26.13 percent. The median yield was 4.340 percent, and the low yield was 4.290 percent. Noncompetitive tenders totaled $90 million. Competitive tenders accepted from private investors totaled $12,910 million. Accrued interest of $0.23481 per $1,000 must be paid for the period from January 15 to January 17. The minimum par amount required for STRIPS of notes of Series D-2011 is $1,000.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [137, 851, 750, 919], \"page_id\": 37}], \"content\": \"Auction of 10-Year Treasury Inflation-Protected Security (TIPS)\", \"description\": null, \"id\": 5, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [138, 936, 800, 1004], \"page_id\": 37}], \"content\": \"On January 9, 2006, Treasury announced it would auction $9,000 million of 10-year TIPS to raise new cash.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 1009, 801, 1193], \"page_id\": 37}], \"content\": \"The 10-year TIPS of Series A-2016 were dated January 15 and issued January 17. They are due January 15, 2016, with interest payable on July 15 and January 15 until maturity. Treasury set an interest rate of 2 percent after determining which tenders were accepted on a yield auction basis.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 1197, 801, 1784], \"page_id\": 37}], \"content\": \"Treasury received tenders for the TIPS before 12 noon e.s.t. for noncompetitive tenders and before 1:00 p.m. e.s.t. for competitive tenders on January 12. Tenders totaled $16,609 million; Treasury accepted $9,000 million. All noncompetitive and successful competitive bidders were allotted securities at the high yield of 2.025 percent with an equivalent price of $99.722833. Treasury accepted in full all competitive tenders at yields lower than 2.025. Tenders at the high yield were allotted 86.56 percent. The median yield was 2.000 percent, and the low yield was 1.001 percent. Noncompetitive tenders totaled $85 million. Competitive tenders accepted from private investors totaled $8,865 million. Adjusted accrued interest of $0.11044 per $1,000 must be paid for the period from January 15 to January 17. Both the unadjusted price of $99.774716 and the unadjusted accrued interest of $0.11050 were adjusted by an index ratio of 0.99948 for the period from January 15 through January 17. The minimum par amount required for STRIPS of TIPS is $1,000.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [829, 264, 1140, 302], \"page_id\": 37}], \"content\": \"Auction of 20-Year TIPS\", \"description\": null, \"id\": 9, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [827, 323, 1494, 389], \"page_id\": 37}], \"content\": \"On January 19, 2006, Treasury announced it would auction $10,000 million of 20-year TIPS to raise new cash.\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [825, 391, 1497, 575], \"page_id\": 37}], \"content\": \"The 20-year TIPS of January 2026 were dated January 15 and issued January 31. They are due January 15, 2026, with interest payable on July 15 and January 15 until maturity. Treasury set an interest rate of 2 percent after determining which tenders were accepted on a yield auction basis.\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [827, 585, 1494, 1047], \"page_id\": 37}], \"content\": \"Treasury received tenders for the TIPS before 12 noon e.s.t. for noncompetitive tenders and before 1:00 p.m. e.s.t. for competitive tenders on January 24. Tenders totaled $14,804 million; Treasury accepted 10,000 million at the high yield of 2.039 percent with an equivalent price of $98,949064. Tenders at the high yield were allotted 3.80 percent. The median yield was 1.955 percent, and the low yield was 1.900 percent. Noncompetitive tenders totaled $42 million. Competitive tenders accepted from private investors totaled $9,908 million. Adjusted accrued interest of $0.88030 per $1,000 must be paid for the period from January 15 to January 31. Both the unadjusted price of $99.362412 and the unadjusted accrued interest of $0.88398 were adjusted by an index ratio of 0.99584 for the period from January 15 through January 31.\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [829, 1056, 1494, 1179], \"page_id\": 37}], \"content\": \"In addition to the $10,000 million of tenders accepted in the auction process, Treasury accepted $1,765 million from FRBs for their own accounts. The minimum par amount required for STRIPS of TIPS is $1,000.\", \"description\": null, \"id\": 13, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 1195, 1142, 1230], \"page_id\": 37}], \"content\": \"Auction of 2-Year Notes\", \"description\": null, \"id\": 14, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [831, 1249, 1494, 1407], \"page_id\": 37}], \"content\": \"On January 23, 2006, Treasury announced it would auction $22,000 million of 2-year notes of Series R-2008. The issue was to refund $25,605 million of securities maturing January 31 and to pay down approximately $3,605 million.\", \"description\": null, \"id\": 15, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [829, 1417, 1494, 1570], \"page_id\": 37}], \"content\": \"The notes of Series R-2008 were dated and issued on January 31. They are due January 31, 2008, with interest payable on July 31 and January 31 until maturity. Treasury set an interest rate of 4-3/8 percent after determining which tenders were accepted on a yield auction basis.\", \"description\": null, \"id\": 16, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 1579, 1494, 1919], \"page_id\": 37}], \"content\": \"Treasury received tenders for the notes before 12 noon e.s.t. for noncompetitive tenders and before 1 p.m. e.s.t. for competitive tenders on January 25. Tenders totaled $46,362 million; Treasury accepted $22,000 million. All noncompetitive and successful competitive bidders were allotted securities at the high yield of 4.427 percent with the equivalent price of $99,901510. Treasury accepted in full all competitive tenders at yields lower than 4.427 percent. Tenders at the high yield were allotted 39.51 percent. The median yield was 4.405 percent, and the low yield was 4.350 percent. Noncompetitive tenders totaled $967 million.\", \"description\": null, \"id\": 17, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1381, 2037, 1492, 2070], \"page_id\": 37}], \"content\": \"June 2006\", \"description\": null, \"id\": 18, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [142, 99, 173, 123], \"page_id\": 38}], \"content\": \"34\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [636, 99, 1000, 125], \"page_id\": 38}], \"content\": \"PUBLIC DEBT OPERATIONS\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [375, 196, 1253, 231], \"page_id\": 38}], \"content\": \"TREASURY FINANCING: JANUARY-MARCH, con.\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [142, 264, 796, 323], \"page_id\": 38}], \"content\": \"Competitive tenders accepted from private investors totaled $21,033 million.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 335, 796, 483], \"page_id\": 38}], \"content\": \"In addition to the $22,000 million of tenders accepted in the auction process, Treasury accepted $5,163 million from Federal Reserve Banks (FRBs) for their own accounts. The minimum par amount required for STRIPS of notes of Series R-2008 is $1,000.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 512, 384, 542], \"page_id\": 38}], \"content\": \"FEBRUARY\", \"description\": null, \"id\": 5, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [144, 573, 519, 603], \"page_id\": 38}], \"content\": \"February Quarterly Financing\", \"description\": null, \"id\": 6, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [144, 629, 796, 834], \"page_id\": 38}], \"content\": \"On February 1, 2006, Treasury announced it would auction $21,000 million of 3-year notes of Series R-2009, $13,000 million of 10-year notes of Series B-2016, and $14,000 million of 30-year bonds of February 2036 to refund $17,281 million of Treasury securities maturing on February 15 and to raise new cash of approximately $30,719 million.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 849, 796, 1030], \"page_id\": 38}], \"content\": \"The 3-year notes of Series R-2009 were dated and issued February 15. They are due February 15, 2009, with interest payable on August 15 and February 15 until maturity. Treasury set an interest rate of 4-1/2 percent after determining which tenders were accepted on a yield auction basis.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 1042, 796, 1436], \"page_id\": 38}], \"content\": \"Treasury received tenders for the notes before 12 noon e.s.t. for noncompetitive tenders and before 1 p.m. e.s.t. for competitive tenders on February 7. Tenders totaled $42,635 million; Treasury accepted $21,000 million. All noncompetitive and successful competitive bidders were allotted securities at the high yield of 4.595 percent with an equivalent price of $99.736583. Treasury accepted in full all competitive tenders at yields lower than 4.595 percent. Tenders at the high yield were allotted 44.01 percent. The median yield was 4.571 percent, and the low yield was 4.538 percent. Noncompetitive tenders totaled $182 million. Competitive tenders accepted from private investors totaled $20,718 million.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 1447, 796, 1568], \"page_id\": 38}], \"content\": \"In addition to the $21,000 million of tenders accepted in the auction process, Treasury accepted $1,307 million from FRBs for their own accounts. The minimum par amount required for STRIPS of notes of Series R-2009 is $1,000.\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 1579, 796, 1758], \"page_id\": 38}], \"content\": \"The 10-year notes of Series B-2016 were dated and issued February 15. They are due February 15, 2016, with interest payable on August 15 and February 15 until maturity. Treasury set an interest rate of 4-1/2 percent after determining which tenders were accepted on a yield auction basis.\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 1770, 796, 1890], \"page_id\": 38}], \"content\": \"Treasury received tenders for the notes before 12 noon e.s.t. for noncompetitive tenders and before 1 p.m. e.s.t. for competitive tenders on February 8. Tenders totaled $30,144 million; Treasury accepted $13,000 million.\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 264, 1488, 535], \"page_id\": 38}], \"content\": \"noncompetitive and successful competitive bidders were allotted securities at the high yield of 4.540 percent with an equivalent price of $99.681335. Treasury accepted in full all competitive tenders at yields lower than 4.540 percent. Tenders at the high yield were allotted 98.55 percent. The median yield was 4.510 percent, and the low yield was 4.470 percent. Noncompetitive tenders totaled $54 million. Competitive tenders accepted from private investors totaled $12,846 million.\", \"description\": null, \"id\": 13, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 549, 1488, 669], \"page_id\": 38}], \"content\": \"In addition to the $13,000 million of tenders accepted in the auction process, Treasury accepted $841 million from FRBs for their own accounts. The minimum par amount required for STRIPS of notes of Series B-2016 is $1,000.\", \"description\": null, \"id\": 14, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 679, 1488, 860], \"page_id\": 38}], \"content\": \"The 30-year bonds of February 2036 were dated and issued February 15. They are due February 15, 2036, with interest payable on August 15 and February 15 until maturity. Treasury set an interest rate of 4-1/2 percent after determining which tenders were accepted on a yield auction basis.\", \"description\": null, \"id\": 15, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 872, 1488, 1266], \"page_id\": 38}], \"content\": \"Treasury received tenders for the notes before 12 noon e.s.t. for noncompetitive tenders and before 1 p.m. e.s.t. for competitive tenders on February 9. Tenders totaled $28,720 million; Treasury accepted $14,000 million. All noncompetitive and successful competitive bidders were allotted securities at the high yield of 4.530 percent with an equivalent price of $99.510492. Treasury accepted in full all competitive tenders at yields lower than 4.530 percent. Tenders at the high yield were allotted 51.17 percent. The median yield was 4.490 percent, and the low yield was 4.475 percent. Noncompetitive tenders totaled $39 million. Competitive tenders accepted from private investors totaled $13,861 million.\", \"description\": null, \"id\": 16, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 1278, 1488, 1398], \"page_id\": 38}], \"content\": \"In addition to the $14,000 million of tenders accepted in the auction process, Treasury accepted $841 million from FRBs for their own accounts. The minimum par amount required for STRIPS of bonds of February 2036 is $1,000.\", \"description\": null, \"id\": 17, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 1424, 1135, 1452], \"page_id\": 38}], \"content\": \"Auction of 2-Year Notes\", \"description\": null, \"id\": 18, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [834, 1483, 1488, 1600], \"page_id\": 38}], \"content\": \"On February 16, 2006, Treasury announced it would auction $22,000 million of 2-year notes. The issue was to refund $26,002 million of securities maturing February 28 and to raise new cash of approximately $9,998 million.\", \"description\": null, \"id\": 19, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 1612, 1488, 1791], \"page_id\": 38}], \"content\": \"The notes of Series S-2008 were dated and issued February 28. They are due February 29, 2008, with interest payable on the last calendar day of August and February until maturity. Treasury set an interest rate of 4-5/8 percent after determining which tenders were accepted on a yield auction basis.\", \"description\": null, \"id\": 20, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 1803, 1488, 1890], \"page_id\": 38}], \"content\": \"Treasury received tenders for the notes before 12:00 noon e.s.t. for noncompetitive tenders and before 1:00 p.m. e.s.t. for competitive tenders on February 22. Tenders totaled\", \"description\": null, \"id\": 21, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 2044, 248, 2067], \"page_id\": 38}], \"content\": \"June 2006\", \"description\": null, \"id\": 22, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [627, 87, 1007, 130], \"page_id\": 39}], \"content\": \"PUBLIC DEBT OPERATIONS\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1450, 85, 1497, 132], \"page_id\": 39}], \"content\": \"35\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [362, 179, 1279, 236], \"page_id\": 39}], \"content\": \"TREASURY FINANCING: JANUARY-MARCH, con.\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [124, 262, 823, 587], \"page_id\": 39}], \"content\": \"$49,265 million; Treasury accepted $22,000 million. All noncompetitive and successful competitive bidders were allotted securities at the high yield of 4.689 percent with an equivalent price of $99.879165. Treasury accepted in full all competitive tenders at yields lower than 4.689 percent. Tenders at the high yield were allotted 81.01 percent. The median yield was 4.660 percent, and the low yield was 4.620 percent. Noncompetitive tenders totaled $1,023 million. Competitive tenders accepted from private investors totaled $20,977 million.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [129, 580, 807, 726], \"page_id\": 39}], \"content\": \"In addition to the $22,000 million of tenders accepted in the auction process, Treasury accepted $4,500 million from FRBs for their own accounts. The minimum par amount required for STRIPS of notes of Series S-2008 is $1,000.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [133, 724, 459, 776], \"page_id\": 39}], \"content\": \"Auction of 5-Year Notes\", \"description\": null, \"id\": 5, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [128, 776, 814, 1098], \"page_id\": 39}], \"content\": \"On February 16, 2006, Treasury announced it would auction $14,000 million of 5-year notes of Series E-2011. The issue was to refund $26,002 million of securities maturing February 28 and to raise new cash of approximately $9,998 million. The notes of Series E-2011 were dated and issued February 28. They are due February 28, 2011, with interest payable on the last calendar day of August and February until maturity. Treasury set an interest rate of 4-1/2 percent after determining which tenders were accepted on a yield auction basis.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [124, 1094, 820, 1506], \"page_id\": 39}], \"content\": \"Treasury received tenders for the notes before 12 noon e.s.t. for noncompetitive tenders and before 1:00 p.m. e.s.t. for competitive tenders on February 23. Tenders totaled $30,502 million; Treasury accepted $14,000 million. All noncompetitive and successful competitive bidders were allotted securities at the high yield of 4.622 percent with an equivalent price of $99,460872. Treasury accepted in full all competitive tenders at yields lower than 4.622 percent. Tenders at the high yield were allotted 56.17 percent. The median yield was 4.594 percent, and the low yield was 4.550 percent. Noncompetitive tenders totaled $147 million. Competitive tenders accepted from private investors totaled $13,853 million.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [124, 1502, 803, 1634], \"page_id\": 39}], \"content\": \"In addition to the $14,000 million of tenders accepted in the auction process, Treasury accepted $3,500 million from FRBs for their own accounts. The minimum par amount required for STRIPS of notes of Series E-2011 is $1,000.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [129, 1638, 317, 1702], \"page_id\": 39}], \"content\": \"MARCH\", \"description\": null, \"id\": 9, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [133, 1704, 452, 1747], \"page_id\": 39}], \"content\": \"Cash Management Bills\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [129, 1763, 809, 1898], \"page_id\": 39}], \"content\": \"On February 28, 2006, Treasury announced it would auction $25,000 million of 12-day bills. They were issued March 3, and matured March 15. The issue was to raise new cash. Treasury auctioned the bills on March 1. Tenders\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [825, 269, 1497, 330], \"page_id\": 39}], \"content\": \"totaled $64,333 million; Treasury accepted 25,000 million. The high bank discount rate was 4.445 percent.\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [820, 332, 1506, 528], \"page_id\": 39}], \"content\": \"On March 6, Treasury announced it would auction $7,000 million of 6-day bills. They were issued March 8 and matured March 14. The issue was to raise new cash. Treasury auctioned the bills on March 7. Tenders totaled $30,051 million; Treasury accepted $7,000 million. The high bank discount rate was 4.380 percent.\", \"description\": null, \"id\": 13, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [821, 526, 1501, 721], \"page_id\": 39}], \"content\": \"On March 13, Treasury announced it would auction $4,000 million of 1-day bills. They were issued March 14 and matured March 15. The issue was to raise new cash. Treasury auctioned the bills on March 14. Tenders totaled $18,006 million; Treasury accepted $4,000 million. The high bank discount rate was 4.410 percent.\", \"description\": null, \"id\": 14, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [820, 728, 1448, 778], \"page_id\": 39}], \"content\": \"Auction of 9-Year 11-Month 4-1/2 Percent Notes\", \"description\": null, \"id\": 15, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [820, 783, 1514, 889], \"page_id\": 39}], \"content\": \"On March 6, 2006, Treasury announced it would auction $8,000 million of 9-year 11-month 4-1/2 percent notes of Series B-2016. The issue was to raise new cash.\", \"description\": null, \"id\": 16, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [818, 891, 1514, 1021], \"page_id\": 39}], \"content\": \"The notes of Series B-2016 were dated February 15 and issued March 15. They are due February 15, 2016, with interest payable on August 15 and February 15 until maturity.\", \"description\": null, \"id\": 17, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [820, 1021, 1517, 1525], \"page_id\": 39}], \"content\": \"Treasury received tenders for the notes before 12 noon e.s.t. for noncompetitive tenders and before 1:00 p.m. e.s.t. for competitive tenders on March 9. Tenders totaled $22,947 million; Treasury accepted $8,000 million. All noncompetitive and successful competitive bidders were allotted securities at the high yield of 4.760 percent with an equivalent price of $97.955698. Treasury accepted in full all competitive tenders at yields lower than 4.760 percent. Tenders at the high yield were allotted 4.91 percent. The median yield was 4.747 percent, and the low yield was 4.710 percent. Noncompetitive tenders totaled $20 million. Competitive tenders accepted from private investors totaled $7,980 million. Accrued interest of $3.48066 per $1,000 must be paid for the period from February 15 to March 15. The minimum par amount required for STRIPS of notes of Series B-2016 is $1,000.\", \"description\": null, \"id\": 18, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [820, 1527, 1146, 1582], \"page_id\": 39}], \"content\": \"Auction of 2-Year Notes\", \"description\": null, \"id\": 19, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [825, 1582, 1501, 1756], \"page_id\": 39}], \"content\": \"On March 23, 2006, Treasury announced it would auction $22,000 million of 2-year notes of Series T-2008. The issue was to refund $26,005 million of securities maturing March 31 and to raise new cash of approximately $9,995 million.\", \"description\": null, \"id\": 20, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [823, 1751, 1501, 1914], \"page_id\": 39}], \"content\": \"The notes of Series T-2008 were dated and issued March 31. They are due March 31, 2008, with interest payable on September 30 and March 31 until maturity. Treasury set an interest rate of 4-5/8 percent after determining which tenders were accepted on a yield auction basis.\", \"description\": null, \"id\": 21, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1373, 2030, 1501, 2072], \"page_id\": 39}], \"content\": \"June 2006\", \"description\": null, \"id\": 22, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [144, 94, 175, 123], \"page_id\": 40}], \"content\": \"36\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [634, 94, 996, 125], \"page_id\": 40}], \"content\": \"PUBLIC DEBT OPERATIONS\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [375, 191, 1255, 229], \"page_id\": 40}], \"content\": \"TREASURY FINANCING: JANUARY-MARCH, con.\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [140, 262, 800, 662], \"page_id\": 40}], \"content\": \"Treasury received tenders for the notes before 12 noon e.s.t. for noncompetitive tenders and before 1:00 p.m. e.s.t. for competitive tenders on March 27. Tenders totaled $46,703 million; Treasury accepted $22,000 million. All noncompetitive and successful competitive bidders were allotted securities at the high yield of 4.730 percent with an equivalent price of $99.801852. Treasury accepted in full all competitive tenders at yields lower than 4.730 percent. Tenders at the high yield were allotted 12.15 percent. The median yield was 4.700 percent, and the low yield was 4.000 percent. Noncompetitive tenders totaled $987 million. Competitive tenders accepted from private investors totaled $21,013 million.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 667, 800, 790], \"page_id\": 40}], \"content\": \"In addition to the $22,000 million of tenders accepted in the auction process, Treasury accepted $4,834 million from FRBs for their own accounts. The minimum par amount required for STRIPS of notes of Series T-2008 is $1,000.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 813, 446, 849], \"page_id\": 40}], \"content\": \"Auction of 5-Year Notes\", \"description\": null, \"id\": 5, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [140, 867, 800, 1021], \"page_id\": 40}], \"content\": \"On March 23, 2006, Treasury announced it would auction $14,000 million of 5-year notes of Series F-2011. The issue was to refund $26,005 million of securities maturing March 31 and to raise new cash of approximately $9,995 million.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 262, 1488, 417], \"page_id\": 40}], \"content\": \"The notes of Series F-2011 were dated and issued March 31. They are due March 31, 2011, with interest payable on September 30 and March 31 until maturity. Treasury set an interest rate of 4-3/4 percent after determining which tenders were accepted on a yield auction basis.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [834, 422, 1492, 820], \"page_id\": 40}], \"content\": \"Treasury received tenders for the notes before 12 noon e.s.t. for noncompetitive tenders and before 1:00 p.m. e.s.t. for competitive tenders on March 29. Tenders totaled $31,555 million; Treasury accepted $14,000 million. All noncompetitive and successful competitive bidders were allotted securities at the high yield of 4.785 percent with an equivalent price of $99.845985. Treasury accepted in full all competitive tenders at yields lower than 4.785 percent. Tenders at the high yield were allotted 18.09 percent. The median yield was 4.761 percent, and the low yield was 4.707 percent. Noncompetitive tenders totaled $156 million. Competitive tenders accepted from private investors totaled $13,844 million.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 827, 1494, 955], \"page_id\": 40}], \"content\": \"In addition to the $14,000 million of tenders accepted in the auction process, Treasury accepted $3,500 million from FRBs for their own accounts. The minimum par amount required for STRIPS of notes of Series F-2011 is $1,000.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 2039, 248, 2067], \"page_id\": 40}], \"content\": \"June 2006\", \"description\": null, \"id\": 10, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [632, 101, 996, 125], \"page_id\": 41}], \"content\": \"PUBLIC DEBT OPERATIONS\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1455, 97, 1488, 125], \"page_id\": 41}], \"content\": \"37\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [182, 198, 1446, 266], \"page_id\": 41}], \"content\": \"TABLE PDO-1.\\u2014Maturity Schedules of Interest-Bearing Marketable Public Debt Securities Other than Regular Weekly and 52-Week Treasury Bills Outstanding, March 31, 2006\", \"description\": null, \"id\": 2, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [158, 278, 1472, 1728], \"page_id\": 41}], \"content\": \"<table><tr><th colspan=\\\"2\\\">Date of final maturity</th><th>Description (1)</th><th>Issue date (2)</th><th>Total (3)</th><th>U.S. Government accounts and Federal Reserve banks (4)</th><th>All other investors (5)</th></tr><tr><td colspan=\\\"7\\\">2006</td></tr><tr><td>Apr. 30</td><td>1 2-1/4%-N note</td><td>04/30/04</td><td>34,335</td><td>8,333</td><td>26,001</td></tr><tr><td>May 15, 06-11</td><td>13-7/8% bond</td><td>05/15/81</td><td>3,545</td><td>1,074</td><td>2,471</td></tr><tr><td>May 15</td><td>1 6-7/8%-B note</td><td>05/15/96</td><td>16,015</td><td>4,311</td><td>11,704</td></tr><tr><td>May 15</td><td>1 4-5/8%-E note</td><td>05/15/01</td><td>27,798</td><td>4,064</td><td>23,734</td></tr><tr><td>May 15</td><td>1 2%-G note</td><td>05/15/03</td><td>22,392</td><td>441</td><td>21,951</td></tr><tr><td>May 31</td><td>1 2-1/2%-P note</td><td>06/01/04</td><t