scription\": null, \"id\": 7, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [138, 94, 188, 132], \"page_id\": 69}], \"content\": \"66\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [658, 92, 976, 132], \"page_id\": 69}], \"content\": \"CAPITAL MOVEMENTS\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [326, 189, 1310, 248], \"page_id\": 69}], \"content\": \"CHART CM-A.\\u2014U.S. Liabilities to Foreigners\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [158, 250, 1474, 297], \"page_id\": 69}], \"content\": \"Reported by U.S. Banks, Brokers, and Dealers with Respect to Selected Countries\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [186, 323, 1135, 1146], \"page_id\": 69}], \"content\": null, \"description\": null, \"id\": 4, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [1144, 368, 1468, 1143], \"page_id\": 69}], \"content\": \"U.S. liabilities to foreigners reported by U.S. banks were recorded at $3.3 trillion in March 2006, an increase of $164 billion from yearend 2005. U.S. banking liabilities include holdings of short-term securities but exclude holdings of long-term securities. U.S. banking liabilities increased about $141 billion in 2005, about $635 billion in 2004, and about $316 billion in 2003. Much of the increase in liabilities to foreigners in 2003 reflects changes to the reporting scope of the TIC reporting system effective February 2003. Between March and December of 2003, when data were reported on a consistent basis, banking liabilities increased about $136 billion.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [188, 1153, 1117, 1285], \"page_id\": 69}], \"content\": \"<table><tr><td><input type=\\\"checkbox\\\"> United Kingdom</td><td><input type=\\\"checkbox\\\"> All other Europe</td><td><input type=\\\"checkbox\\\" checked> Caribbean banking centers</td></tr><tr><td><input type=\\\"checkbox\\\"> Japan</td><td><input type=\\\"checkbox\\\"> All other Asia</td><td><input type=\\\"checkbox\\\"> All other countries</td></tr></table>\", \"description\": null, \"id\": 6, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [1138, 1183, 1468, 1716], \"page_id\": 69}], \"content\": \"U.S. banking liabilities are concentrated in international financial centers. The data on this page show that more than half of U.S. banking liabilities is currently recorded against the United Kingdom and banking centers in the Caribbean. These financial centers have recorded most of the growth in banking liabilities in recent years. Foreigners domiciled in the rest of Europe and in Asia account for about one-third of U.S. banking liabilities.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [188, 1325, 1117, 1742], \"page_id\": 69}], \"content\": \"<table><tr><th colspan=\\\"6\\\">[In millions of dollars. Source: Treasury International Capital Reporting System]</th></tr><tr><th rowspan=\\\"2\\\">Country</th><th colspan=\\\"5\\\">Calendar years</th></tr><tr><th>2002</th><th>2003</th><th>2004</th><th>2005</th><th>Mar. 2006</th></tr><tr><td>United Kingdom</td><td>203,237</td><td>345,235</td><td>501,721</td><td>579,920</td><td>647,957</td></tr><tr><td>All other Europe</td><td>483,421</td><td>462,334</td><td>611,774</td><td>680,573</td><td>720,203</td></tr><tr><td>Caribbean banking centers 1,2</td><td>837,771</td><td>955,536</td><td>1,186,221</td><td>1,200,803</td><td>1,274,049</td></tr><tr><td>Japan</td><td>176,331</td><td>170,315</td><td>173,872</td><td>159,930</td><td>142,941</td></tr><tr><td>All other Asia</td><td>162,938</td><td>214,276</td><td>260,142</td><td>257,307</td><td>239,436</td></tr><tr><td>Subtotal</td><td>1,863,698</td><td>2,147,696</td><td>2,733,730</td><td>2,878,533</td><td>3,024,586</td></tr><tr><td>All other countries</td><td>202,433</td><td>234,774</td><td>284,143</td><td>280,815</td><td>298,927</td>