d Caribbean.\\\"\\n6 Beginning January 2001, Cayman Islands replaced British West Indies in the data series.\", \"description\": null, \"id\": 6, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [1382, 2039, 1497, 2086], \"page_id\": 74}], \"content\": \"June 2006\", \"description\": null, \"id\": 7, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [144, 101, 175, 123], \"page_id\": 75}], \"content\": \"72\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [668, 97, 965, 125], \"page_id\": 75}], \"content\": \"CAPITAL MOVEMENTS\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [344, 203, 1262, 259], \"page_id\": 75}], \"content\": \"CHART CM-B.\\u2014U.S. Claims on Foreigners\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [173, 259, 1435, 304], \"page_id\": 75}], \"content\": \"Reported by U.S. Banks, Brokers, and Dealers with Respect to Selected Countries\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [193, 351, 1073, 1311], \"page_id\": 75}], \"content\": null, \"description\": null, \"id\": 4, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [1117, 370, 1470, 1016], \"page_id\": 75}], \"content\": \"In December 2005, U.S. claims on foreigners reported by U.S. banks amounted to about $2.4 trillion, an increase of $235 billion from the level recorded at yearend 2004. U.S. banking claims include holdings of short-term securities but exclude holdings of long-term securities. U.S. banking claims increased $488 billion in 2004 and $183 billion in 2003. In large part, the increase in claims in 2003 reflects changes to the reporting scope of the TIC reporting system effective February 2003. Between March and December of 2003, when data were reported on a consistent basis, banking claims increased $12 billion.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1122, 1058, 1472, 1494], \"page_id\": 75}], \"content\": \"As with U.S. banking liabilities, U.S. banking claims on foreigners are concentrated in international financial centers. About 60 percent of these claims are reported opposite the United Kingdom and banking centers in the Caribbean. The share of claims against foreigners domiciled in Asia has declined over the past several years from about 20 percent at the end of 1996 to less than 10 percent currently.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [158, 1372, 1073, 1883], \"page_id\": 75}], \"content\": null, \"description\": null, \"id\": 7, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [135, 2048, 253, 2074], \"page_id\": 75}], \"content\": \"June 2006\", \"description\": null, \"id\": 8, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [658, 92, 973, 127], \"page_id\": 76}], \"content\": \"CAPITAL MOVEMENTS\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1448, 90, 1494, 132], \"page_id\": 76}], \"content\": \"73\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [313, 182, 1319, 290], \"page_id\": 76}], \"content\": \"SECTION III.\\u2014Supplementary Liabilities and Claims Data Reported by Banks in the United States\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [279, 288, 1326, 380], \"page_id\": 76}], \"content\": \"TABLE CM-III-1.\\u2014Dollar Liabilities to, and Dollar Claims on, Foreigners in Countries and Areas Not Regularly Reported Separately\", \"description\": null, \"id\": 3, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [424, 377, 1189, 410], \"page_id\": 76}], \"content\": \"[Position at end of period in millions of dollars. Source: Treasury International Capital Reporting System]\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 410, 1470, 1780], \"page_id\": 76}], \"content\": \"<table><tr><th rowspan=\\\"2\\\">Country</th><